#include <bits/stdc++.h>
using namespace std;

struct Parser {
    string s;
    int pos = 0;
    vector< set<int> > *setsPtr;
    set<int> universal;

    Parser(const string& str, vector< set<int> > *sp, const set<int>& u)
        : s(str), setsPtr(sp), universal(u) {}

    void skipSpaces() {
        while (pos < (int)s.size() && isspace((unsigned char)s[pos])) pos++;
    }

    set<int> set_union_op(const set<int>& a, const set<int>& b) {
        set<int> r;
        std::set_union(a.begin(), a.end(), b.begin(), b.end(),
                       inserter(r, r.begin()));
        return r;
    }

    set<int> set_intersection_op(const set<int>& a, const set<int>& b) {
        set<int> r;
        std::set_intersection(a.begin(), a.end(), b.begin(), b.end(),
                              inserter(r, r.begin()));
        return r;
    }

    set<int> set_difference_op(const set<int>& a, const set<int>& b) {
        set<int> r;
        std::set_difference(a.begin(), a.end(), b.begin(), b.end(),
                            inserter(r, r.begin()));
        return r;
    }

    set<int> set_symdiff_op(const set<int>& a, const set<int>& b) {
        set<int> r;
        std::set_symmetric_difference(a.begin(), a.end(), b.begin(), b.end(),
                                      inserter(r, r.begin()));
        return r;
    }

    set<int> parseExpression() { // lowest precedence: union, symdiff
        set<int> left = parseTerm();
        skipSpaces();
        while (pos < (int)s.size()) {
            char c = s[pos];
            if (c == 'u' || c == '+' || c == '|') {
                pos++;
                set<int> right = parseTerm();
                left = set_union_op(left, right);
            } else if (c == '^') {
                pos++;
                set<int> right = parseTerm();
                left = set_symdiff_op(left, right);
            } else {
                break;
            }
            skipSpaces();
        }
        return left;
    }

    set<int> parseTerm() { // middle precedence: intersection, difference
        set<int> left = parseFactor();
        skipSpaces();
        while (pos < (int)s.size()) {
            char c = s[pos];
            if (c == '&' || c == '*') {
                pos++;
                set<int> right = parseFactor();
                left = set_intersection_op(left, right);
            } else if (c == '-' || c == '\\') {
                pos++;
                set<int> right = parseFactor();
                left = set_difference_op(left, right);
            } else {
                break;
            }
            skipSpaces();
        }
        return left;
    }

    set<int> parseFactor() { // highest precedence: complement
        skipSpaces();
        if (pos < (int)s.size() && (s[pos] == '!' || s[pos] == '~')) {
            pos++;
            set<int> inner = parseFactor();
            return set_difference_op(universal, inner);
        }
        return parsePrimary();
    }

    set<int> parsePrimary() {
        skipSpaces();
        if (pos < (int)s.size() && s[pos] == '(') {
            pos++;
            set<int> val = parseExpression();
            skipSpaces();
            if (pos < (int)s.size() && s[pos] == ')') pos++;
            return val;
        }

        // Parse set identifier: A..Z or a positive integer index
        if (pos < (int)s.size() && isalpha((unsigned char)s[pos])) {
            char c = s[pos++];
            int idx;
            if ('A' <= c && c <= 'Z') idx = c - 'A';
            else idx = c - 'a';
            if (0 <= idx && idx < (int)setsPtr->size()) return (*setsPtr)[idx];
            return {};
        }

        if (pos < (int)s.size() && isdigit((unsigned char)s[pos])) {
            int num = 0;
            while (pos < (int)s.size() && isdigit((unsigned char)s[pos])) {
                num = num * 10 + (s[pos] - '0');
                pos++;
            }
            // support both 0-based and 1-based naturally:
            if (0 <= num && num < (int)setsPtr->size()) return (*setsPtr)[num];
            if (1 <= num && num <= (int)setsPtr->size()) return (*setsPtr)[num - 1];
            return {};
        }

        return {};
    }
};

