import sys

def solve():
    data = sys.stdin.read().strip().splitlines()
    if not data:
        return

    idx = 0
    first = data[idx].strip().split()
    idx += 1

    if len(first) == 1:
        n = int(first[0])
        q = int(data[idx].strip())
        idx += 1
    else:
        n, q = map(int, first)

    sets_map = {}
    universal = set()

    for _ in range(n):
        parts = data[idx].strip().split()
        idx += 1
        name = parts[0]
        nums = set(map(int, parts[1:])) if len(parts) > 1 else set()
        sets_map[name] = nums
        universal |= nums

    # Tokenizer for expressions
    def tokenize(s):
        tokens = []
        i = 0
        while i < len(s):
            c = s[i]
            if c.isspace():
                i += 1
            elif c in '()+-*^~':
                tokens.append(c)
                i += 1
            else:
                j = i
                while j < len(s) and (s[j].isalnum() or s[j] == '_'):
                    j += 1
                tokens.append(s[i:j])
                i = j
        return tokens

    # Recursive descent parser
    # precedence:
    # ~ highest (unary complement)
    # * intersection
    # + union, - difference, ^ symmetric difference
    def parse_expression(tokens):
        pos = 0

        def parse_term():
            nonlocal pos
            node = parse_factor()
            while pos < len(tokens) and tokens[pos] == '*':
                op = tokens[pos]
                pos += 1
                rhs = parse_factor()
                node = (op, node, rhs)
            return node

        def parse_expr():
            nonlocal pos
            node = parse_term()
            while pos < len(tokens) and tokens[pos] in ('+', '-', '^'):
                op = tokens[pos]
                pos += 1
                rhs = parse_term()
                node = (op, node, rhs)
            return node

        def parse_factor():
            nonlocal pos
            if tokens[pos] == '~':
                pos += 1
                return ('~', parse_factor())
            if tokens[pos] == '(':
                pos += 1
                node = parse_expr()
                if pos < len(tokens) and tokens[pos] == ')':
                    pos += 1
                return node
            name = tokens[pos]
            pos += 1
            return ('set', name)

        return parse_expr()

    def eval_ast(ast):
        t = ast[0]
        if t == 'set':
            return sets_map.get(ast[1], set())
        if t == '~':
            return universal - eval_ast(ast[1])
        a = eval_ast(ast[1])
        b = eval_ast(ast[2])
        if t == '+':
            return a | b
        if t == '*':
            return a & b
        if t == '-':
            return a - b
        if t == '^':
            return a ^ b
        return set()

    out = []
    for _ in range(q):
        expr = data[idx].strip()
        idx += 1
        tokens = tokenize(expr)
        ast = parse_expression(tokens)
        res = sorted(eval_ast(ast))
        out.append("{" + ",".join(map(str, res)) + "}")

    sys.stdout.write("\n".join(out))

