import java.io.*;
import java.util.*;

public class SetOperations {
    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        String line;
        Map<String, Set<Integer>> sets = new HashMap<>();
        List<String> operations = new ArrayList<>();
        boolean readingSets = true;

        while ((line = br.readLine()) != null) {
            line = line.trim();
            if (line.isEmpty()) continue;
            if (readingSets) {
                if (line.equals("---")) {
                    readingSets = false;
                    continue;
                }
                // Parse set definition: name = {elements}
                String[] parts = line.split("=", 2);
                String name = parts[0].trim();
                String elementsPart = parts[1].trim();
                // Remove braces
                elementsPart = elementsPart.substring(1, elementsPart.length() - 1).trim();
                Set<Integer> set = new HashSet<>();
                if (!elementsPart.isEmpty()) {
                    String[] nums = elementsPart.split(",");
                    for (String num : nums) {
                        set.add(Integer.parseInt(num.trim()));
                    }
                }
                sets.put(name, set);
            } else {
                operations.add(line);
            }
        }

        // Compute universal set
        Set<Integer> universal = new HashSet<>();
        for (Set<Integer> set : sets.values()) {
            universal.addAll(set);
        }

        // Process each operation
        for (String op : operations) {
            // Tokenize operation
            String[] tokens = op.split(" ");
            // Build result step by step using two stacks: one for sets, one for operators
            Deque<Set<Integer>> setStack = new ArrayDeque<>();
            Deque<String> opStack = new ArrayDeque<>();

            for (int i = 0; i < tokens.length; i++) {
                String token = tokens[i];
                if (token.equals("(")) {
                    opStack.push(token);
                } else if (token.equals(")")) {
                    while (!opStack.isEmpty() && !opStack.peek().equals("(")) {
                        applyOp(setStack, opStack.pop(), universal);
                    }
                    opStack.pop(); // remove '('
                } else if (isOperator(token)) {
                    while (!opStack.isEmpty() && precedence(opStack.peek()) >= precedence(token)) {
                        applyOp(setStack, opStack.pop(), universal);
                    }
                    opStack.push(token);
                } else {
                    // It's a set name or a constant set like {1,2,3}
                    Set<Integer> set;
                    if (token.startsWith("{")) {
                        // Parse inline set
                        String inner = token.substring(1, token.length() - 1);
                        set = new HashSet<>();
                        if (!inner.isEmpty()) {
                            String[] nums = inner.split(",");
                            for (String num : nums) {
                                set.add(Integer.parseInt(num.trim()));
                            }
                        }
                    } else {
                        set = sets.get(token);
                        if (set == null) {
                            set = new HashSet<>();
                        }
                    }
                    setStack.push(new HashSet<>(set));
                }
            }
            while (!opStack.isEmpty()) {
                applyOp(setStack, opStack.pop(), universal);
            }

            Set<Integer> result = setStack.pop();
            // Output result
            List<Integer> sorted = new ArrayList<>(result);
            Collections.sort(sorted);
            StringBuilder sb = new StringBuilder("{");
            for (int j = 0; j < sorted.size(); j++) {
                if (j > 0) sb.append(",");
                sb.append(sorted.get(j));
            }
            sb.append("}");
            System.out.println(sb.toString());
        }
    }

    private static boolean isOperator(String s) {
        return s.equals("U") || s.equals("I") || s.equals("D") || s.equals("S") || s.equals("C");
    }

    private static int precedence(String op) {
        // Complement has highest precedence, then intersection/difference/symmetric difference, then union
        if (op.equals("C")) return 3;
        if (op.equals("I") || op.equals("D") || op.equals("S")) return 2;
        if (op.equals("U")) return 1;
        return 0;
    }

    private static void applyOp(Deque<Set<Integer>> stack, String op, Set<Integer> universal) {
        if (op.equals("C")) {
            Set<Integer> a = stack.pop();
            Set<Integer> result = new HashSet<>(universal);
            result.removeAll(a);
            stack.push(result);
        } else {
            Set<Integer> b = stack.pop();
            Set<Integer> a = stack.pop();
            Set<Integer> result;
            switch (op) {
                case "U":
                    result = new HashSet<>(a);
                    result.addAll(b);
                    break;
                case "I":
                    result = new HashSet<>(a);
                    result.retainAll(b);
                    break;
                case "D":
                    result = new HashSet<>(a);
                    result.removeAll(b);
                    break;
                case "S":
                    result = new HashSet<>(a);
                    result.addAll(b);
                    Set<Integer> inter = new HashSet<>(a);
                    inter.retainAll(b);
                    result.removeAll(inter);
                    break;
                default:
                    result = new HashSet<>();
            }
            stack.push(result);
        }
    }
}

