public class Main {
    static Map<String, TreeSet<Integer>> sets = new LinkedHashMap<>();
    static TreeSet<Integer> universal = new TreeSet<>();
    static String expr;
    static int pos;

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        // Read set definitions until blank line or query marker
        List<String> lines = new ArrayList<>();
        while (sc.hasNextLine()) {
            lines.add(sc.nextLine());
        }

        // Parse sets first (lines with '='), then evaluate expressions
        for (String line : lines) {
            line = line.trim();
            if (line.isEmpty()) continue;
            if (line.contains("=")) {
                // Set definition
                String[] parts = line.split("=", 2);
                String name = parts[0].trim();
                String setStr = parts[1].trim();
                TreeSet<Integer> s = parseSet(setStr);
                sets.put(name, s);
                universal.addAll(s);
            } else {
                // Expression to evaluate
                expr = line.replaceAll("\\s+", "");
                pos = 0;
                TreeSet<Integer> result = parseExpr();
                System.out.println(result.toString().replace(" ", ""));
            }
        }
    }

    static TreeSet<Integer> parseSet(String s) {
        TreeSet<Integer> result = new TreeSet<>();
        s = s.trim();
        if (s.equals("{}")) return result;
        s = s.replaceAll("[{}]", "");
        for (String t : s.split(",")) {
            t = t.trim();
            if (!t.isEmpty()) result.add(Integer.parseInt(t));
        }
        return result;
    }

    // Expression parser: handles union (+), difference (-), symmetric diff (^)
    static TreeSet<Integer> parseExpr() {
        TreeSet<Integer> left = parseTerm();
        while (pos < expr.length() && (expr.charAt(pos) == '+' || expr.charAt(pos) == '-' || expr.charAt(pos) == '^')) {
            char op = expr.charAt(pos++);
            TreeSet<Integer> right = parseTerm();
            if (op == '+') { left.addAll(right); }
            else if (op == '-') { left.removeAll(right); }
            else { // symmetric difference
                TreeSet<Integer> union = new TreeSet<>(left);
                union.addAll(right);
                TreeSet<Integer> inter = new TreeSet<>(left);
                inter.retainAll(right);
                union.removeAll(inter);
                left = union;
            }
        }
        return left;
    }

    static TreeSet<Integer> parseTerm() {
        TreeSet<Integer> left = parsePrimary();
        while (pos < expr.length() && expr.charAt(pos) == '*') {
            pos++;
            TreeSet<Integer> right = parsePrimary();
            left.retainAll(right);
        }
        return left;
    }

    static TreeSet<Integer> parsePrimary() {
        TreeSet<Integer> result;
        if (pos < expr.length() && expr.charAt(pos) == '(') {
            pos++; // '('
            result = parseExpr();
            pos++; // ')'
        } else {
            // Set name (single letter assumed)
            String name = String.valueOf(expr.charAt(pos++));
            result = new TreeSet<>(sets.getOrDefault(name, new TreeSet<>()));
        }
        // Handle complement postfix '
        while (pos < expr.length() && expr.charAt(pos) == '\'') {
            pos++;
            TreeSet<Integer> comp = new TreeSet<>(universal);
            comp.removeAll(result);
            result = comp;
        }
        return result;
    }
}

import java.io.*;
import java.util.*;

/*
Assumptions based on the statement:
- Input contains several named integer sets, then several expressions to evaluate.
- Universal set U is the union of all explicitly defined sets.
- Supported operators:
    union                : |
    intersection         : &
    difference           : -
    symmetric difference : ^
    complement           : !
- Parentheses are supported.
- Set names are identifiers.
- Output each resulting set in increasing order as:
    {a,b,c}
  or {} for empty set.

Because the original statement omits the exact input format, this solution supports a common flexible format:

Input:
n
name1 k a1 a2 ... ak
...
namen k ...
q
expression1
...
expressionq

Example:
3
A 3 1 2 3
B 3 3 4 5
C 2 5 6
4
A|B
A&B
A-(B^C)
!(A&B)

This parser reads expressions line by line.

Operator precedence:
! highest (unary, right-associative)
& next
- next
^ next
| lowest
Parentheses override.

If a referenced set name is undefined, it is treated as empty.
*/

public class Main {
    static class FastScanner {
        private final InputStream in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        FastScanner(InputStream is) {
            in = is;
        }

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        String next() throws IOException {
            StringBuilder sb = new StringBuilder();
            int c;
            do {
                c = read();
                if (c == -1) return null;
            } while (Character.isWhitespace(c));
            while (c != -1 && !Character.isWhitespace(c)) {
                sb.append((char) c);
                c = read();
            }
            return sb.toString();
        }

        String nextLine() throws IOException {
            StringBuilder sb = new StringBuilder();
            int c = read();
            if (c == -1) return null;
            while (c == '\r' || c == '\n') {
                c = read();
                if (c == -1) return "";
            }
            while (c != -1 && c != '\n' && c != '\r') {
                sb.append((char) c);
                c = read();
            }
            return sb.toString();
        }

        Integer nextIntNullable() throws IOException {
            String s = next();
            if (s == null) return null;
            return Integer.parseInt(s);
        }

        int nextInt() throws IOException {
            return Integer.parseInt(next());
        }
    }

    static Map<String, TreeSet<Integer>> sets = new HashMap<>();
    static TreeSet<Integer> universal = new TreeSet<>();

    static class Parser {
        String s;
        int pos;

        Parser(String s) {
            this.s = s;
            this.pos = 0;
        }

        TreeSet<Integer> parse() {
            TreeSet<Integer> res = parseUnion();
            skip();
            return res;
        }

        // lowest: |
        TreeSet<Integer> parseUnion() {
            TreeSet<Integer> left = parseXor();
            while (true) {
                skip();
                if (match('|')) {
                    TreeSet<Integer> right = parseXor();
                    left = union(left, right);
                } else {
                    break;
                }
            }
            return left;
        }

        // ^
        TreeSet<Integer> parseXor() {
            TreeSet<Integer> left = parseDiff();
            while (true) {
                skip();
                if (match('^')) {
                    TreeSet<Integer> right = parseDiff();
                    left = symDiff(left, right);
                } else {
                    break;
                }
            }
            return left;
        }

        // -
        TreeSet<Integer> parseDiff() {
            TreeSet<Integer> left = parseInter();
            while (true) {
                skip();
                if (match('-')) {
                    TreeSet<Integer> right = parseInter();
                    left = diff(left, right);
                } else {
                    break;
                }
            }
            return left;
        }

        // &
        TreeSet<Integer> parseInter() {
            TreeSet<Integer> left = parseUnary();
            while (true) {
                skip();
                if (match('&')) {
                    TreeSet<Integer> right = parseUnary();
                    left = inter(left, right);
                } else {
                    break;
                }
            }
            return left;
        }

        // !
        TreeSet<Integer> parseUnary() {
            skip();
            if (match('!')) {
                TreeSet<Integer> x = parseUnary();
                return complement(x);
            }
            return parsePrimary();
        }

        TreeSet<Integer> parsePrimary() {
            skip();
            if (match('(')) {
                TreeSet<Integer> res = parseUnion();
                skip();
                match(')');
                return res;
            }

            String name = parseIdentifier();
            if (name == null) return new TreeSet<>();
            return new TreeSet<>(sets.getOrDefault(name, new TreeSet<>()));
        }

        String parseIdentifier() {
            skip();
            if (pos >= s.length()) return null;
            char c = s.charAt(pos);
            if (!Character.isLetter(c) && c != '_') return null;
            int start = pos++;
            while (pos < s.length()) {
                c = s.charAt(pos);
                if (Character.isLetterOrDigit(c) || c == '_') pos++;
                else break;
            }
            return s.substring(start, pos);
        }

        void skip() {
            while (pos < s.length() && Character.isWhitespace(s.charAt(pos))) pos++;
        }

        boolean match(char ch) {
            skip();
            if (pos < s.length() && s.charAt(pos) == ch) {
                pos++;
                return true;
            }
            return false;
        }
    }

    static TreeSet<Integer> union(Set<Integer> a, Set<Integer> b) {
        TreeSet<Integer> r = new TreeSet<>(a);
        r.addAll(b);
        return r;
    }

    static TreeSet<Integer> inter(Set<Integer> a, Set<Integer> b) {
        TreeSet<Integer> r = new TreeSet<>();
        for (int x : a) if (b.contains(x)) r.add(x);
        return r;
    }

    static TreeSet<Integer> diff(Set<Integer> a, Set<Integer> b) {
        TreeSet<Integer> r = new TreeSet<>();
        for (int x : a) if (!b.contains(x)) r.add(x);
        return r;
    }

    static TreeSet<Integer> symDiff(Set<Integer> a, Set<Integer> b) {
        TreeSet<Integer> r = new TreeSet<>();
        for (int x : a) if (!b.contains(x)) r.add(x);
        for (int x : b) if (!a.contains(x)) r.add(x);
        return r;
    }

    static TreeSet<Integer> complement(Set<Integer> a) {
        TreeSet<Integer> r = new TreeSet<>();
        for (int x : universal) if (!a.contains(x)) r.add(x);
        return r;
    }

    static String formatSet(Set<Integer> set) {
        StringBuilder sb = new StringBuilder();
        sb.append('{');
        boolean first = true;
        for (int x : set) {
            if (!first) sb.append(',');
            first = false;
            sb.append(x);
        }
        sb.append('}');
        return sb.toString();
    }

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner(System.in);
        Integer nObj = fs.nextIntNullable();
        if (nObj == null) return;
        int n = nObj;

        for (int i = 0; i < n; i++) {
            String name = fs.next();
            int k = fs.nextInt();
            TreeSet<Integer> cur = new TreeSet<>();
            for (int j = 0; j < k; j++) {
                int v = fs.nextInt();
                cur.add(v);
                universal.add(v);
            }
            sets.put(name, cur);
        }

        int q = fs.nextInt();
        StringBuilder out = new StringBuilder();

        for (int i = 0; i < q; i++) {
            String line = fs.nextLine();
            while (line != null && line.trim().isEmpty()) line = fs.nextLine();
            if (line == null) line = "";
            Parser parser = new Parser(line);
            TreeSet<Integer> ans = parser.parse();
            out.append(formatSet(ans)).append('\n');
        }

        System.out.print(out.toString());
    }
