#define MAX_SETS 100
#define MAX_ELEMENTS 1000
#define MAX_LINE 10000

int sets[MAX_SETS][MAX_ELEMENTS];
int set_sizes[MAX_SETS];
int num_sets;
int universal[MAX_ELEMENTS];
int universal_size;

// Helper to compare for qsort
int cmp(const void *a, const void *b) {
    return *(int*)a - *(int*)b;
}

// Remove duplicates from sorted array
int unique(int arr[], int size) {
    if (size == 0) return 0;
    int j = 0;
    for (int i = 1; i < size; i++) {
        if (arr[i] != arr[j]) {
            j++;
            arr[j] = arr[i];
        }
    }
    return j + 1;
}

// Read a set definition line and store in sets
int read_set_line(char *line, int set_idx) {
    char *token = strtok(line, " ");
    int count = 0;
    while (token) {
        sets[set_idx][count++] = atoi(token);
        token = strtok(NULL, " ");
    }
    qsort(sets[set_idx], count, sizeof(int), cmp);
    set_sizes[set_idx] = unique(sets[set_idx], count);
    return 1;
}

// Build universal set from all sets
void build_universal() {
    int temp[MAX_ELEMENTS * MAX_SETS];
    int idx = 0;
    for (int i = 0; i < num_sets; i++) {
        for (int j = 0; j < set_sizes[i]; j++) {
            temp[idx++] = sets[i][j];
        }
    }
    qsort(temp, idx, sizeof(int), cmp);
    idx = unique(temp, idx);
    universal_size = idx;
    for (int i = 0; i < idx; i++) universal[i] = temp[i];
}

// Check if element is in set (set must be sorted)
int in_set(int elem, int arr[], int size) {
    int lo = 0, hi = size - 1;
    while (lo <= hi) {
        int mid = (lo + hi) / 2;
        if (arr[mid] == elem) return 1;
        if (arr[mid] < elem) lo = mid + 1;
        else hi = mid - 1;
    }
    return 0;
}

// Set operations
void union_sets(int a[], int sa, int b[], int sb, int res[], int *sr) {
    int temp[MAX_ELEMENTS * 2];
    int idx = 0;
    for (int i = 0; i < sa; i++) temp[idx++] = a[i];
    for (int i = 0; i < sb; i++) temp[idx++] = b[i];
    qsort(temp, idx, sizeof(int), cmp);
    idx = unique(temp, idx);
    for (int i = 0; i < idx; i++) res[i] = temp[i];
    *sr = idx;
}

void intersect(int a[], int sa, int b[], int sb, int res[], int *sr) {
    int idx = 0;
    for (int i = 0; i < sa; i++) {
        if (in_set(a[i], b, sb)) {
            res[idx++] = a[i];
        }
    }
    *sr = idx;
}

void difference(int a[], int sa, int b[], int sb, int res[], int *sr) {
    int idx = 0;
    for (int i = 0; i < sa; i++) {
        if (!in_set(a[i], b, sb)) {
            res[idx++] = a[i];
        }
    }
    *sr = idx;
}

void sym_diff(int a[], int sa, int b[], int sb, int res[], int *sr) {
    int temp1[MAX_ELEMENTS], s1;
    int temp2[MAX_ELEMENTS], s2;
    difference(a, sa, b, sb, temp1, &s1);
    difference(b, sb, a, sa, temp2, &s2);
    union_sets(temp1, s1, temp2, s2, res, sr);
}

void complement(int a[], int sa, int res[], int *sr) {
    int idx = 0;
    for (int i = 0; i < universal_size; i++) {
        if (!in_set(universal[i], a, sa)) {
            res[idx++] = universal[i];
        }
    }
    *sr = idx;
}

// Evaluate expression recursively
typedef struct {
    int data[MAX_ELEMENTS];
    int size;
} SetResult;

SetResult eval_expr(char **expr) {
    SetResult result;

    // Skip spaces
    while (**expr == ' ') (*expr)++;

    // If starts with '('
    if (**expr == '(') {
        (*expr)++; // skip '('
        SetResult left = eval_expr(expr);
        while (**expr == ' ') (*expr)++;
        char op = **expr;
        (*expr)++;
        while (**expr == ' ') (*expr)++;
        SetResult right = eval_expr(expr);
        while (**expr == ' ') (*expr)++;
        if (**expr == ')') (*expr)++; // skip ')'

        switch (op) {
            case 'U':
                union_sets(left.data, left.size, right.data, right.size, result.data, &result.size);
                break;
            case 'I':
                intersect(left.data, left.size, right.data, right.size, result.data, &result.size);
                break;
            case 'D':
                difference(left.data, left.size, right.data, right.size, result.data, &result.size);
                break;
            case 'S':
                sym_diff(left.data, left.size, right.data, right.size, result.data, &result.size);
                break;
        }
    }
    // If starts with 'C' (complement)
    else if (**expr == 'C') {
        (*expr)++; // skip 'C'
        SetResult inner = eval_expr(expr);
        complement(inner.data, inner.size, result.data, &result.size);
    }
    // Otherwise it's a set number
    else {
        int num = 0;
        while (isdigit(**expr)) {
            num = num * 10 + (**expr - '0');
            (*expr)++;
        }
        result.size = set_sizes[num];
        for (int i = 0; i < result.size; i++) result.data[i] = sets[num][i];
    }

    return result;
}

int main() {
    char line[MAX_LINE];
    int reading_sets = 1;
    num_sets = 0;

    while (fgets(line, MAX_LINE, stdin)) {
        // Remove newline
        int len = strlen(line);
        if (len > 0 && line[len-1] == '\n') line[len-1] = '\0';

        // Skip empty lines
        if (strlen(line) == 0) continue;

        // Check if this is a set definition (starts with digit)
        if (reading_sets && isdigit(line[0])) {
            read_set_line(line, num_sets);
            num_sets++;
        } else {
            // First non-set line: build universal and process expressions
            if (reading_sets) {
                build_universal();
                reading_sets = 0;
            }

            char *ptr = line;
            SetResult res = eval_expr(&ptr);

            // Print result
            if (res.size == 0) {
                printf("empty\n");
            } else {
                for (int i = 0; i < res.size; i++) {
                    if (i > 0) printf(" ");
                    printf("%d", res.data[i]);
                }
                printf("\n");
            }
        }
    }

    return 0;
}

