#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <ctype.h>

#define MAXSETS 26
#define MAXELEMS 20000
#define MAXLINE 100000

typedef struct {
    int *a;
    int n;
} Set;

static Set sets[MAXSETS];
static int universe_arr[MAXELEMS];
static int universe_n = 0;

static char expr[MAXLINE];
static int posi;

/* ---------- Utility ---------- */

static int cmp_int(const void *p1, const void *p2) {
    int a = *(const int *)p1;
    int b = *(const int *)p2;
    if (a < b) return -1;
    if (a > b) return 1;
    return 0;
}

static void normalize_set(Set *s) {
    if (s->n == 0) return;
    qsort(s->a, s->n, sizeof(int), cmp_int);
    int j = 0;
    for (int i = 0; i < s->n; i++) {
        if (i == 0 || s->a[i] != s->a[j - 1]) {
            s->a[j++] = s->a[i];
        }
    }
    s->n = j;
}

static Set copy_set(const Set *s) {
    Set r;
    r.n = s->n;
    if (r.n == 0) {
        r.a = NULL;
        return r;
    }
    r.a = (int *)malloc(sizeof(int) * r.n);
    memcpy(r.a, s->a, sizeof(int) * r.n);
    return r;
}

static void free_set(Set *s) {
    free(s->a);
    s->a = NULL;
    s->n = 0;
}

/* ---------- Set operations ---------- */

static Set set_union(const Set *x, const Set *y) {
    Set r;
    r.a = (int *)malloc(sizeof(int) * (x->n + y->n));
    int i = 0, j = 0, k = 0;
    while (i < x->n && j < y->n) {
        if (x->a[i] < y->a[j]) r.a[k++] = x->a[i++];
        else if (x->a[i] > y->a[j]) r.a[k++] = y->a[j++];
        else {
            r.a[k++] = x->a[i];
            i++; j++;
        }
    }
    while (i < x->n) r.a[k++] = x->a[i++];
    while (j < y->n) r.a[k++] = y->a[j++];
    r.n = k;
    return r;
}

static Set set_intersection(const Set *x, const Set *y) {
    Set r;
    r.a = (int *)malloc(sizeof(int) * (x->n < y->n ? x->n : y->n));
    int i = 0, j = 0, k = 0;
    while (i < x->n && j < y->n) {
        if (x->a[i] < y->a[j]) i++;
        else if (x->a[i] > y->a[j]) j++;
        else {
            r.a[k++] = x->a[i];
            i++; j++;
        }
    }
    r.n = k;
    return r;
}

static Set set_difference(const Set *x, const Set *y) {
    Set r;
    r.a = (int *)malloc(sizeof(int) * x->n);
    int i = 0, j = 0, k = 0;
    while (i < x->n && j < y->n) {
        if (x->a[i] < y->a[j]) r.a[k++] = x->a[i++];
        else if (x->a[i] > y->a[j]) j++;
        else {
            i++; j++;
        }
    }
    while (i < x->n) r.a[k++] = x->a[i++];
    r.n = k;
    return r;
}

static Set set_symdiff(const Set *x, const Set *y) {
    Set r;
    r.a = (int *)malloc(sizeof(int) * (x->n + y->n));
    int i = 0, j = 0, k = 0;
    while (i < x->n && j < y->n) {
        if (x->a[i] < y->a[j]) r.a[k++] = x->a[i++];
        else if (x->a[i] > y->a[j]) r.a[k++] = y->a[j++];
        else {
            i++; j++;
        }
    }
    while (i < x->n) r.a[k++] = x->a[i++];
    while (j < y->n) r.a[k++] = y->a[j++];
    r.n = k;
    return r;
}

static Set set_complement(const Set *x) {
    Set u;
    u.a = universe_arr;
    u.n = universe_n;
    return set_difference(&u, x);
}

/* ---------- Parser ----------
Grammar used:

expr    := diff
diff    := sym { '-' sym }
sym     := inter { '^' inter }
inter   := uni { '&' uni }
uni     := unary { '|' unary }
unary   := '!' unary | primary
primary := LETTER | '(' expr ')'

This gives precedence:
! highest, then |, then &, then ^, then -
If your judge uses a different precedence, adjust accordingly.
-------------------------------- */

static void skip_spaces(void) {
    while (expr[posi] && isspace((unsigned char)expr[posi])) posi++;
}

static Set parse_expr(void);

static Set parse_primary(void) {
    skip_spaces();
    if (expr[posi] == '(') {
        posi++;
        Set r = parse_expr();
        skip_spaces();
        if (expr[posi] == ')') posi++;
        return r;
    }
    if (isalpha((unsigned char)expr[posi])) {
        int id = toupper((unsigned char)expr[posi]) - 'A';
        posi++;
        return copy_set(&sets[id]);
    }
    Set empty;
    empty.a = NULL;
    empty.n = 0;
    return empty;
}

static Set parse_unary(void) {
    skip_spaces();
    if (expr[posi] == '!') {
        posi++;
        Set x = parse_unary();
        Set r = set_complement(&x);
        free_set(&x);
        return r;
    }
    return parse_primary();
}

static Set parse_union_level(void) {
    Set left = parse_unary();
    while (1) {
        skip_spaces();
        if (expr[posi] != '|') break;
        posi++;
        Set right = parse_unary();
        Set tmp = set_union(&left, &right);
        free_set(&left);
        free_set(&right);
        left = tmp;
    }
    return left;
}

static Set parse_intersection_level(void) {
    Set left = parse_union_level();
    while (1) {
        skip_spaces();
        if (expr[posi] != '&') break;
        posi++;
        Set right = parse_union_level();
        Set tmp = set_intersection(&left, &right);
        free_set(&left);
        free_set(&right);
        left = tmp;
    }
    return left;
}

static Set parse_symdiff_level(void) {
    Set left = parse_intersection_level();
    while (1) {
        skip_spaces();
        if (expr[posi] != '^') break;
        posi++;
        Set right = parse_intersection_level();
        Set tmp = set_symdiff(&left, &right);
        free_set(&left);
        free_set(&right);
        left = tmp;
    }
    return left;
}

static Set parse_diff_level(void) {
    Set left = parse_symdiff_level();
    while (1) {
        skip_spaces();
        if (expr[posi] != '-') break;
        posi++;
        Set right = parse_symdiff_level();
        Set tmp = set_difference(&left, &right);
        free_set(&left);
        free_set(&right);
        left = tmp;
    }
    return left;
}

static Set parse_expr(void) {
    return parse_diff_level();
}

/* ---------- Output ---------- */

static void print_set(const Set *s) {
    printf("{");
    for (int i = 0; i < s->n; i++) {
        if (i) printf(",");
        printf("%d", s->a[i]);
    }
    printf("}\n");
}

