    char line[MAXLINE];

    for (int i = 0; i < n; i++) {
        if (!fgets(line, sizeof(line), stdin)) return 0;

        int id = -1;
        for (int j = 0; line[j]; j++) {
            if (isalpha((unsigned char)line[j])) {
                id = toupper((unsigned char)line[j]) - 'A';
                break;
            }
        }
        if (id < 0 || id >= MAXSETS) continue;

        int *tmp = (int *)malloc(sizeof(int) * MAXELEMS);
        int cnt = 0;

        char *p = line;
        while (*p) {
            if (*p == '-' || isdigit((unsigned char)*p)) {
                char *endp;
                long v = strtol(p, &endp, 10);
                tmp[cnt++] = (int)v;
                p = endp;
            } else {
                p++;
            }
        }

        sets[id].a = (int *)malloc(sizeof(int) * cnt);
        memcpy(sets[id].a, tmp, sizeof(int) * cnt);
        sets[id].n = cnt;
        normalize_set(&sets[id]);

        for (int j = 0; j < sets[id].n; j++) {
            universe_arr[universe_n++] = sets[id].a[j];
        }
        free(tmp);
    }

    qsort(universe_arr, universe_n, sizeof(int), cmp_int);
    int uu = 0;
    for (int i = 0; i < universe_n; i++) {
        if (i == 0 || universe_arr[i] != universe_arr[uu - 1]) {
            universe_arr[uu++] = universe_arr[i];
        }
    }
    universe_n = uu;

    int q;
    if (scanf("%d", &q) != 1) q = 0;
    getchar();

    for (int i = 0; i < q; i++) {
        if (!fgets(expr, sizeof(expr), stdin)) break;
        posi = 0;
